import json,subprocess,copy,sys
RUN=['/app/submission/run.sh']
base=json.load(open('/app/examples/empty.json'))

def runraw(data):
 p=subprocess.run(RUN,input=data,stdout=subprocess.PIPE,stderr=subprocess.PIPE,timeout=20)
 if p.returncode!=0:raise AssertionError((p.returncode,p.stderr))
 return json.loads(p.stdout)
def run(req):return runraw(json.dumps(req,separators=(',',':')).encode())
def expect(req,error='E_SCHEMA'):
 got=run(req)
 assert got=={'error':error},(got,req)
def mutate(path,value):
 r=copy.deepcopy(base);x=r
 for p in path[:-1]:x=x[p]
 x[path[-1]]=value;return r
# JSON-level classification.
for raw in [b'',b' ',b'{',b'{} trailing',b'\xef\xbb\xbf{}',b'\xff',b'{"a":1,"a":2}',b'NaN',b'{"x":Infinity}',b'[1,]',b'\x00']:
 assert runraw(raw)=={'error':'E_JSON'},raw
assert runraw(b'['*65+b'0'+b']'*65)=={'error':'E_JSON'}
assert runraw(b'['*64+b'0'+b']'*64)=={'error':'E_SCHEMA'}
assert runraw(b'{"x":1e999999999999999999999999}')=={'error':'E_SCHEMA'}
assert runraw(b'{"x":'+b'9'*5000+b'}')=={'error':'E_SCHEMA'}
# Exact keys / scalar types.
for key in list(base):expect(mutate([key],None) if key!='version' else mutate(['version'],2))
r=copy.deepcopy(base);r['extra']=1;expect(r)
for value in [True,1.0,'1',None,0,2,-1]:expect(mutate(['version'],value))
for value in [True,0,9,1.0,'1',None]:expect(mutate(['window'],value))
for key,val in [('max_width',0),('max_width',5),('max_width',True),('min_support',0),('min_support',4097),('min_witness',0),('min_witness',1.0)]:expect(mutate(['policy',key],val))
r=copy.deepcopy(base);r['policy']['x']=1;expect(r)
# Schema definitions and domains.
for value in [None,{},[],[base['schema'][0]]*33]:expect(mutate(['schema'],value))
r=copy.deepcopy(base);r['schema']=[{'name':'a','type':'SIZE','min':0,'max':1},{'name':'a','type':'FLAG'}];expect(r)
for name in ['', 'A', 'a-', 'a'*33, '0a', 'a.b', 'é']:
 r=copy.deepcopy(base);r['schema'][0]['name']=name;expect(r)
for lo,hi in [(1,0),(-2147483649,0),(0,2147483648),(True,1),(0,1.0)]:
 r=copy.deepcopy(base);r['schema']=[{'name':'a','type':'SIZE','min':lo,'max':hi}];expect(r)
for vals in [[],['a','a'],['a']*33,[''],['a'*33],['bad!'],[1],['a',True]]:
 r=copy.deepcopy(base);r['schema']=[{'name':'a','type':'ID','values':vals}];expect(r)
# Atom shape, term type/depth/nodes, offsets, constants.
def withatom(a):
 r=copy.deepcopy(base);r['atoms']=[a];return r
valid={'cmp':'eq','left':{'field':'a','at':0},'right':{'const':True,'type':'FLAG'}}
assert run(withatom(valid))['version']==1
bad_atoms=[None,{},[],dict(valid,x=1),
 {'quantifier':'any','from':0,'to':0,'predicate':{'quantifier':'all','from':0,'to':0,'predicate':valid}},
 {'cmp':'lt','left':{'field':'a','at':0},'right':{'const':True,'type':'FLAG'}},
 {'cmp':'eq','left':{'field':'a','at':0},'right':{'const':1,'type':'FLAG'}},
 {'cmp':'eq','left':{'field':'a','at':0},'right':{'const':False,'type':'SIZE'}},
 {'cmp':'eq','left':{'field':'a','at':0},'right':{'const':False,'type':'FLAG','x':1}},
 {'cmp':'eq','left':{'field':'a','at':'$'},'right':{'const':False,'type':'FLAG'}},
 {'cmp':'eq','left':{'field':'a','at':1},'right':{'const':False,'type':'FLAG'}},
 {'cmp':'eq','left':{'field':'b','at':0},'right':{'const':False,'type':'FLAG'}},
 {'cmp':'eq','left':{'scale':1,'term':{'field':'a','at':0}},'right':{'const':False,'type':'FLAG'}},
 {'cmp':'eq','left':{'add':[{'field':'a','at':0},{'field':'a','at':0}]},'right':{'const':False,'type':'FLAG'}},
 {'cmp':'eq','left':{'aggregate':'mean','field':'a','from':0,'to':0},'right':{'const':False,'type':'FLAG'}},
]
for a in bad_atoms:expect(withatom(a))
r=copy.deepcopy(base);r['schema']=[{'name':'x','type':'SIZE','min':-5,'max':5}]
for c in [{'const':1.0,'type':'SIZE'},{'const':True,'type':'SIZE'},{'const':2147483648,'type':'SIZE'},{'const':-2147483649,'type':'SIZE'},{'const':'bad!','type':'ID'},{'const':'okay','type':'NO'}]:
 expect(withatom({'cmp':'eq','left':{'field':'x','at':0},'right':c}))
for scale in [-1025,1025,True,1.0]:
 expect(withatom({'cmp':'eq','left':{'scale':scale,'term':{'field':'x','at':0}},'right':{'const':1,'type':'SIZE'}}))
# depth five (four nested scales then a field) is invalid; four total is valid.
t={'field':'x','at':0}
for i in range(3):t={'scale':1,'term':t}
assert run(withatom({'cmp':'eq','left':t,'right':{'const':1,'type':'SIZE'}}))['version']==1
expect(withatom({'cmp':'eq','left':{'scale':1,'term':t},'right':{'const':1,'type':'SIZE'}}))
for q in [('any',0,1),('all',1,0),('any',-1,0),('all',0,0)]:
 a={'quantifier':q[0],'from':q[1],'to':q[2],'predicate':{'cmp':'eq','left':{'field':'a','at':'$'},'right':{'const':True,'type':'FLAG'}}}
 if q[1:]==(0,0):
  # Window is one in base: only the malformed quantifier string case is tested below.
  pass
 if q[0]=='any' and q[1:]==(0,0):continue
 expect(withatom(a))
# Traces and rows.
tr={'id':'t','source':'s','rows':[{'t':0,'values':[True,True]}]}
for part in ['train','probes','queries']:
 r=copy.deepcopy(base);r[part]=[tr];assert run(r)['version']==1
for traceid,source in [('', 's'),('0a','s'),('a'*33,'s'),('a',''),('a','0s'),('a','s'*33)]:
 r=copy.deepcopy(base);r['train']=[dict(tr,id=traceid,source=source)];expect(r)
r=copy.deepcopy(base);r['train']=[tr];r['probes']=[tr];expect(r)
r=copy.deepcopy(base);r['train']=[tr,dict(tr,id='u')];expect(r)
r=copy.deepcopy(base);r['train']=[{'id':'t','source':'s','rows':[{'t':0,'values':[True,True]},{'t':0,'values':[False,False]}]}];expect(r)
r=copy.deepcopy(base);r['train']=[{'id':'t','source':'s','rows':[{'t':1.0,'values':[True,True]}]}];expect(r)
for vals in [[],[True],[True,1],[True,None],[True,True,True]]:
 r=copy.deepcopy(base);r['train']=[{'id':'t','source':'s','rows':[{'t':0,'values':vals}]}];expect(r)
# Unknown row/trace keys.
r=copy.deepcopy(base);r['train']=[copy.deepcopy(tr)];r['train'][0]['x']=1;expect(r)
r=copy.deepcopy(base);r['train']=[copy.deepcopy(tr)];r['train'][0]['rows'][0]['x']=1;expect(r)
# Atoms/counts and sources.
r=copy.deepcopy(base);r['atoms']=[valid]*21;expect(r)
r=copy.deepcopy(base);r['train']=[dict(tr,id='t%d'%i,source='s%d'%i,rows=[]) for i in range(17)];expect(r)
r=copy.deepcopy(base);r['train']=[dict(tr,id='t%d'%i,source='s',rows=[]) for i in range(129)];expect(r)
# Limit precedence, including malformed oversized input.
data=json.dumps(base,separators=(',',':')).encode();exact=data+b' '*(8388608-len(data));assert len(exact)==8388608 and runraw(exact)['version']==1
assert runraw(exact+b' ')=={'error':'E_LIMIT'}
assert runraw(b'x'*(8388609))=={'error':'E_LIMIT'}
print('validation/error tests passed')
